            invoke(pick.missingStoragePost, overrides.missingStoragePost),
            invoke(pick.patientGetAllPatients, overrides.patientGetAllPatients),
            invoke(pick.patientPost, overrides.patientPost),
            invoke(pick.prescriptionGetAllPrescriptions, overrides.prescriptionGetAllPrescriptions),
            invoke(pick.prescriptionPost, overrides.prescriptionPost),
            invoke(pick.roomBookingGetAll, overrides.roomBookingGetAll),
            invoke(pick.roomBookingPost, overrides.roomBookingPost),
            invoke(pick.staffGetAllStaffs, overrides.staffGetAllStaffs),
            invoke(pick.staffPost, overrides.staffPost),
            invoke(pick.storageGetAllMedicationStorages, overrides.storageGetAllMedicationStorages),
            invoke(pick.storagePost, overrides.storagePost),
            invoke(pick.treatmentGetAllTreatments, overrides.treatmentGetAllTreatments),
            invoke(pick.treatmentPost, overrides.treatmentPost),
            invoke(pick.treatmentStaffGetAll, overrides.treatmentStaffGetAll),
            invoke(pick.treatmentStaffPost, overrides.treatmentStaffPost),
